$cfg = @{}
Get-Content -LiteralPath '.env' | ForEach-Object {
  if ($_ -match '^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=(.*)$') { $cfg[$matches[1]] = $matches[2].Trim().Trim('"').Trim("'") }
}
$sshTarget = $cfg['JI_TEST_SSH_TARGET']
$sshKey = $cfg['JI_TEST_SSH_KEY']
$archive = '/export/user\.gold-band\projects\e-projects-code-ai-ji--a40d4379\tasks\task-015\runs\run-001\rounds\round-001\nodes\ai-dynamic\attempt-001\dynamic\nodes\phase-2-parallel-capabilities-merge\attempt-001\attachments\stage2-linux-source.tgz'
& ssh -i $sshKey -o BatchMode=yes -o StrictHostKeyChecking=yes -- $sshTarget 'set -eu; target=/home/ubuntu/.ji-stage2-validation/run-001; resolved=$(realpath -m -- "$target"); test "$resolved" = "$target"; test ! -e "$target"; mkdir -p "$target/source"'
if ($LASTEXITCODE -ne 0) { throw "Remote validation directory creation failed: $LASTEXITCODE" }
& scp -q -i $sshKey -o BatchMode=yes -o StrictHostKeyChecking=yes -- $archive ($sshTarget + ':/home/ubuntu/.ji-stage2-validation/run-001/source.tgz')
if ($LASTEXITCODE -ne 0) { throw "Linux source upload failed: $LASTEXITCODE" }
& ssh -i $sshKey -o BatchMode=yes -o StrictHostKeyChecking=yes -- $sshTarget 'set -eu; cd /home/ubuntu/.ji-stage2-validation/run-001; actual=$(sha256sum source.tgz | cut -d " " -f 1); test "$actual" = e7a843c4643719afec145951909f4f191d061c4fbae60e242866ea5587fd6b20; tar -xzf source.tgz -C source; printf "linux_source_ready sha256=%s\n" "$actual"'
if ($LASTEXITCODE -ne 0) { throw "Linux source verification failed: $LASTEXITCODE" }

